#include <iostream>
#include <algorithm>
#include <cstdio>
#include <cstring>
using namespace std;

int n_input, k_input, p_input;

int binpow(int base, int exp) {
    int res = 1;
    int cur = base;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * cur % p_input;
        cur = (long long)cur * cur % p_input;
        exp >>= 1;
    }
    return res;
}

int getBit(int x) {
    return x & (-x);
}

int dp[26][250010];
int factorials[250010], invs[250010];

void precompute() {
    factorials[0] = 1;
    for (int i = 1; i <= n_input; ++i)
        factorials[i] = (long long)factorials[i - 1] * i % p_input;
    invs[n_input] = binpow(factorials[n_input], p_input - 2);
    for (int i = n_input; i >= 1; --i)
        invs[i - 1] = (long long)invs[i] * i % p_input;
}

int recurse(int current, int S) {
    if (dp[current][S] != -1) return dp[current][S];
    if (S == 0) {
        dp[current][S] = factorials[n_input];
        for (int i = 1; i <= current; ++i)
            dp[current][S] = (long long)dp[current][S] * (k_input - i + 1) % p_input;
        return dp[current][S];
    }
    dp[current][S] = 0;
    int U = S - getBit(S);
    for (int T = U; T; T = (T - 1) & U)
        dp[current][S] = (dp[current][S] + (long long)invs[S - T] * recurse(current + 1, T)) % p_input;
    dp[current][S] = (dp[current][S] + (long long)invs[S] * recurse(current + 1, 0)) % p_input;
    return dp[current][S];
}

int main() {
    scanf("%d %d %d", &n_input, &k_input, &p_input);
    int answer = 1;
    for (int i = 1; i <= n_input; ++i)
        answer = (long long)answer * k_input % p_input;
    if (n_input % 2 == 0) {
        precompute();
        memset(dp, -1, sizeof(dp));
        answer = (answer - recurse(0, n_input) + p_input) % p_input;
    }
    printf("%d\n", answer);
    return 0;
}
